#include <stdio.h>

/* teste do desafio dobro-caixa — counter_protocol (03-tdd 3.9.3).
   Tres cenarios com valores diferentes (2, 7 e -3 — o terceiro chega como
   conta 0 - 3): nenhum texto fixo no
   printf do aluno passa nos tres, e o negativo prova que a conta e a conta.
   Cada cenario manda o stdout para o SEU arquivo com freopen, chama a caixa
   do aluno e le o arquivo de volta; o fflush descarrega sem fechar, deixando
   o stdout legal para o proximo freopen. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void dobroCaixa(int n);

SM_TEST(o_dobro_de_2) {
    freopen("sm_saida_1.tmp", "w", stdout);
    dobroCaixa(2);
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha do dobro de 2", linha, "o dobro de 2 e 4\n",
              "o argumento 2 entrou pela janela e a conta deu 4");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("uma chamada, uma linha", fim, "(nada impresso)",
              "cada chamada imprime uma linha so");
    fclose(f);
}

SM_TEST(o_dobro_de_7) {
    freopen("sm_saida_2.tmp", "w", stdout);
    dobroCaixa(7);
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha do dobro de 7", linha, "o dobro de 7 e 14\n",
              "a MESMA caixa, agora com 7 na janela: a conta deu 14");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("uma chamada, uma linha", fim, "(nada impresso)",
              "cada chamada imprime uma linha so");
    fclose(f);
}

SM_TEST(o_dobro_de_menos_3) {
    freopen("sm_saida_3.tmp", "w", stdout);
    dobroCaixa(0 - 3);  /* o valor -3 chega pela janela, aqui escrito como conta */
    fflush(stdout);

    FILE *f = fopen("sm_saida_3.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha do dobro de -3", linha, "o dobro de -3 e -6\n",
              "com um valor negativo a caixa faz a MESMA conta: -3 vezes 2 da -6");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("uma chamada, uma linha", fim, "(nada impresso)",
              "cada chamada imprime uma linha so");
    fclose(f);
}

